using Microsoft.Extensions.Logging;

namespace Pragmatic.Logging.Benchmarks.Modules;

/// <summary>
///     The same two methods of the query executor as Pragmatic.Persistence.EFCore declares them today:
///     generated by Microsoft, written fully qualified for that reason. Instance methods finding the logger in
///     a <c>_logger</c> field, as the executor's do.
/// </summary>
internal sealed partial class EfCoreMicrosoftLog(ILogger logger)
{
    private readonly ILogger _logger = logger;

    [Microsoft.Extensions.Logging.LoggerMessage(Level = LogLevel.Debug, Message = EfCoreCallSiteLog.QueryCompletedTemplate)]
    public partial void LogQueryCompleted(string queryType, int totalCount, int page, int pageSize);

    [Microsoft.Extensions.Logging.LoggerMessage(Level = LogLevel.Error, Message = EfCoreCallSiteLog.QueryFailedTemplate)]
    public partial void LogQueryFailed(string queryType, string errorType, Exception ex);
}
